{Player(native).Name="Observed A";native.Step(new());Check(Boss(native).MaximumHP==400&&Boss(native).HP==200,"Native additive scaling preserves current HP fraction before caps");Player(native).Name="Observed B";native.Advance(new(),1000);Check(Boss(native).MaximumHP==400,"Scaling countdown does not rescan before the later comparison tick");native.Step(new());Check(Boss(native).MaximumHP==500&&Boss(native).HP==250,"A newly observed name rescans on the native 1100 ms tick");native.Advance(new(),1000);native.Step(new());Check(Boss(native).MaximumHP==500,"Already counted names do not scale twice even across later scans");}
using(var native=Session("new ScaleHP(100,50,scaleAfter:0)")){native.Step(new());Check(Boss(native).MaximumHP==350&&Boss(native).HP==175,"Native maximum addition caps its first batch and HP conversion");}
using(var native=Session("new ScaleHP(100,50,healAfterMax:false,scaleAfter:0)")){Player(native).Name="Observed A";native.Step(new());Boss(native).HP=100;Player(native).Name="Observed B";native.Advance(new(),1000);native.Step(new());Check(Boss(native).MaximumHP==350&&Boss(native).HP==100,"healAfterMax false consumes new names without updating capped HP");}
using(var native=Session("new ScaleHP(100,50,healAfterMax:true,scaleAfter:0)")){Player(native).Name="Observed A";native.Step(new());Boss(native).HP=100;Player(native).Name="Observed B";native.Advance(new(),1000);native.Step(new());Check(Boss(native).MaximumHP==350&&Boss(native).HP==Convert.ToInt32(400*100d/350),"healAfterMax true retains native pre-cap HP conversion order");}
using(var native=Session("new ScaleHP(100,0,dist:6,scaleAfter:0)")){native.Step(new());Check(Boss(native).MaximumHP==300,"Positive additive scaling range has a strict distance boundary");}
using(var native=Session("new ScaleHP(100,0,dist:0,scaleAfter:0)",new(Invulnerable:true,StartX:76.5))){Player(native).ApplyConditionEffect(ConditionEffectIndex.Hidden,-1);native.Step(new());Check(Boss(native).MaximumHP==400,"Zero additive range counts world entries including Hidden players outside ordinary range");}
using(var native=Session("new ScaleHP(100,0)")){native.Step(new());Check(Boss(native).MaximumHP==300,"Native additive scaling default waits beyond its first player name");}
using(var native=Session("new ScaleDefense(2.5,range:7)")){var original=Boss(native).ObjectDesc.Defense;Boss(native).Defense=999;Player(native).ApplyConditionEffect(ConditionEffectIndex.Invisible,-1);native.Step(new());Check(Boss(native).Defense==original+3,"Native defense scaling overwrites live defense from XML baseline and ceiling of names");Player(native).Move(76.5f,64.5f);native.Advance(new(),1000);native.Step(new());Check(Boss(native).Defense==original+3,"Defense scaling retains counted names after they leave range");}
using(var native=Session("new ScaleDefense(2.5,range:6)")){native.Step(new());Check(Boss(native).Defense==Boss(native).ObjectDesc.Defense,"Defense player acquisition has the native strict range boundary");}
using(var native=Session("new ScaleHP2(10)")){var host=Boss(native);var gear=RapleAdapter.ScalingWeaponInfo(native.Weapon.Id)!;var added=10*host.ObjectDesc.MaxHP/100+gear.NativeGearPoints*host.ObjectDesc.MaxHP/40;native.Step(new());Check(host.MaximumHP==300+added&&host.HP==150+added,"Native percent scaling uses XML max HP, integer math and selected weapon gear flags");Check(Player(native).Inventory[0]!=null&&Enumerable.Range(1,3).All(i=>Player(native).Inventory[i]==null),"Prototype gear evidence explicitly contains its weapon and three empty loadout slots");}
var special=GameWeapon.Catalog().FirstOrDefault(w=>w.Supported&&RapleAdapter.ScalingWeaponInfo(w.Id)?.NativeGearPoints==23);
if(special!=null)using(var native=Session("new ScaleHP2(10)",new(Invulnerable:true,WeaponId:special.Id))){var host=Boss(native);var added=10*host.ObjectDesc.MaxHP/100+23*host.ObjectDesc.MaxHP/40;native.Step(new());Check(host.MaximumHP==300+added,"Legendary/Mythical weapon contributes the original 19-plus-4 native gear points");Player(native).Name="Another observed name";Player(native).Inventory[0]=null;native.Advance(new(),1000);native.Step(new());Check(host.MaximumHP==300+added+10*host.ObjectDesc.MaxHP/100-23*host.ObjectDesc.MaxHP/40,"Later percent batches retain the native signed item-count difference rather than normalizing its accumulator");}
using(var native=Session("new ScaleHP2(10,range:0)")){native.Step(new());Check(Boss(native).MaximumHP==300,"Zero percent-scaling range does not mean a world-wide query");}
using(var native=new EncounterSession(adapter,Doc("new ConditionEffectBehavior(ConditionEffectIndex.Invulnerable),new RemoveConditionalEffect(ConditionEffectIndex.Invulnerable)"),entity,7,new(Invulnerable:true)))
{native.Step(new());Check(!Boss(native).HasConditionEffect(ConditionEffectIndex.Invulnerable),"Entry removal follows source order after an applied native host condition");Boss(native).ApplyConditionEffect(ConditionEffectIndex.Invulnerable,-1);native.Step(new());Check(Boss(native).HasConditionEffect(ConditionEffectIndex.Invulnerable),"Native removal does not refresh during ongoing ticks");}
var remove=Doc("new OnDeathBehavior(new RemoveConditionalEffect(ConditionEffectIndex.Invulnerable))");Check(adapter.EffectiveCallbacks(remove,remove.AllNodes.Single(n=>n.Kind=="RemoveConditionalEffect")).Select(c=>c.Stage).SequenceEqual(new[]{"Death"}),"Lifecycle inspector follows the native death wrapper's entry dispatch");
using(var native=new EncounterSession(adapter,Doc("new TransferDamageOnDeath(\""+recipient+"\",10)"),entity,7,new(Invulnerable:true),arena:new(){Actors=[new(recipient,64.5,67.5)]}))
{var host=Boss(native);var target=World(native).Enemies.Values.Single(e=>e.ObjectDesc.IdName==recipient);target.DamageCounter.HitBy(Player(native),12);native.SetBossHpFraction(0);native.Advance(new(Attack:true),1000);var frame=native.Entities.Single(e=>e.Name==recipient);Check(native.BossHp==0&&target.DamageCounter.TotalDamage==host.DamageCounter.TotalDamage&&target.DamageCounter.LastHitter==host.DamageCounter.LastHitter,"Actual weapon death copies native recorded total and last hitter to the distinct recipient");Check(frame.Damage!.PresentPlayerDamage==host.DamageCounter.GetPlayerData().Sum(p=>p.Item2)+12&&frame.Damage.ParentActorId==null,"Native transfer adds contributor data without creating a damage-counter parent link");}
var doc=Doc("new RemoveConditionalEffect(ConditionEffectIndex.Invulnerable)");var node=doc.AllNodes.Single(n=>n.Kind=="RemoveConditionalEffect");var before=doc.Source;adapter.ApplyConditionAction(doc,entity,node.Id,doc.Revision,ConditionEffectIndex.Armored);Check(adapter.ReadConditionAction(doc,doc.Find(node.Id))==ConditionEffectIndex.Armored&&doc.Undo()&&doc.Source==before&&doc.Redo()&&doc.Find(node.Id).Id==node.Id,"Typed condition selection retains exact source identity and history");doc.LockedNodes.Add(node.Id);Reject(()=>adapter.ApplyConditionAction(doc,entity,node.Id,doc.Revision,ConditionEffectIndex.Weak),"Condition selector respects source region locks");doc.LockedNodes.Clear();Reject(()=>adapter.ApplyConditionAction(doc,entity,node.Id,doc.Revision-1,ConditionEffectIndex.Weak),"Stale condition proposals reject atomically");
var sourceFile=adapter.Catalog().Single(e=>e.Id==entity).SourceFile;var supplied=File.ReadAllText(sourceFile);var body="new ScaleHP(100,0,scaleAfter:0),new ScaleDefense(2.5),new ScaleHP2(10)";var source="using TKR.WorldServer.logic.behaviors;namespace TKR.WorldServer.logic{public partial class BehaviorDb{private _ StudioDefense=()=>Behav().Init(\""+entity+"\",new State(\"scaling\","+body+"));}}";var project=new StudioProject{SourceFile=sourceFile,Source=source,EntityId=entity,Seed=7,Player=new(Invulnerable:true)};
var constantSource=source.Replace(body,"new RemoveConditionalEffect(global::TKR.Shared.resources.ConditionEffectIndex.Invulnerable)");var constantDoc=new BehaviorDocument(constantSource,adapter,sourceFile:sourceFile);Check(adapter.ReadConditionAction(constantDoc,constantDoc.AllNodes.Single(n=>n.Kind=="RemoveConditionalEffect"))==ConditionEffectIndex.Invulnerable,"Compiler-bound byte-backed condition constants resolve without an enum namespace import");
using(var native=new EncounterSession(adapter,Doc(body),entity,7,project.Player)){native.Advance(new(),300);await using var compiled=await CompiledRuntime.StartAsync(adapter.ServerRoot,project);await compiled.AdvanceAsync(new(),300);Check(native.Entities.Single().Hp==compiled.Entities.Single().Hp&&native.Entities.Single().MaxHp==compiled.Entities.Single().MaxHp&&native.Entities.Single().Defense==compiled.Entities.Single().Defense,"Combined literal and compiled scaling retain original source-order HP and defense results");}
var shared="using TKR.WorldServer.logic.behaviors;namespace TKR.WorldServer.logic{public partial class BehaviorDb{static readonly ScaleHP StudioSharedScaling=new(100,0,scaleAfter:0);private _ StudioDefenseShared=()=>Behav().Init(\""+entity+"\",new State(\"scaling\",StudioSharedScaling));}}";await using(var native=await CompiledRuntime.StartAsync(adapter.ServerRoot,project with{Source=shared,Arena=new(){Actors=[new(entity,64.5,67.5)]}})){await native.AdvanceAsync(new(),100);Check(native.Entities.Count==2&&native.Entities.All(e=>e.MaxHp==BossBase()+100),"Shared readonly additive scaler retains independent native state for two actors");}
int BossBase()=>EntityResources.Catalog(EntityResourceScope.Enemy).First(e=>e.Id==entity).MaxHp;
